INSERT INTO cmd_command_type VALUES('board_route_passengers','Board route passengers and collect fares');
INSERT INTO cmd_domain_event_type VALUES('route_passengers_boarded','Route passengers boarded');
CREATE TABLE cmd_passenger_boarding_receipt(command_id bigint PRIMARY KEY REFERENCES cmd_command(command_id),campaign_id bigint NOT NULL REFERENCES camp_campaign(campaign_id),journey_id bigint NOT NULL,ship_id bigint NOT NULL,actor_id bigint NOT NULL,passenger_count integer NOT NULL CHECK(passenger_count>0),total_fare_minor bigint NOT NULL CHECK(total_fare_minor>=0),financial_transaction_id bigint NOT NULL UNIQUE,balance_after_minor bigint NOT NULL,FOREIGN KEY(journey_id,campaign_id) REFERENCES journey_journey(journey_id,campaign_id),FOREIGN KEY(ship_id,campaign_id) REFERENCES ship_ship(ship_id,campaign_id),FOREIGN KEY(actor_id,campaign_id) REFERENCES actor_actor(actor_id,campaign_id),FOREIGN KEY(financial_transaction_id,campaign_id) REFERENCES fin_transaction(transaction_id,campaign_id));
CREATE TABLE cmd_passenger_boarding_line(command_id bigint NOT NULL REFERENCES cmd_passenger_boarding_receipt(command_id),line_order integer NOT NULL CHECK(line_order>0),campaign_id bigint NOT NULL,journey_passage_id bigint NOT NULL UNIQUE,fare_minor bigint NOT NULL CHECK(fare_minor>=0),PRIMARY KEY(command_id,line_order),FOREIGN KEY(journey_passage_id,campaign_id) REFERENCES journey_passage(journey_passage_id,campaign_id));
